/* ÇEVİRİ id · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("id","olay",{
"OLAYLAR_EK9:1899-01-19:0":{"b": ["Perjanjian Kondominium — pemerintahan bersama Inggris-Mesir atas Sudan", "8033c688"], "d": ["Perjanjian yang ditandatangani di Kairo empat bulan setelah Omdurman menempatkan Sudan di bawah pemerintahan bersama kedua negara dengan nama 'Sudan Anglo-Mesir': dua bendera akan dikibarkan bersama, dan gubernur jenderal diangkat oleh khedive dengan persetujuan Inggris. Dalam praktik pemerintahan sepenuhnya di tangan Inggris. Kesultanan Utsmani tidak menjadi pihak dan tidak mengakui perjanjian itu dengan alasan hak atas Sudan melalui Mesir adalah miliknya; tetapi secara de facto ia tersisih. Dengan perjanjian ini wilayah Sudan di selatan paralel ke-22 (Dongola, Khartoum, Sennar, Kordofan, pesisir Suakin, dll.) beralih ke pemerintahan bersama Inggris-Mesir (Sudan Anglo-Mesir).", "097331bb"]},
"OLAYLAR_EK9:1911-10-08:0":{"b": ["Pendaratan Italia di Tobruk — pendudukan pertama di Tripolitania", "44780018"], "d": ["Italia menyatakan perang pada 29 September 1911 dan armadanya memblokade pantai pada 25-26 September. Operasi darat pertama dilakukan di Tobruk pada 8 Oktober: garnisun kecil Utsmani mundur ke pedalaman dan pelabuhan diduduki tanpa pertempuran. Tobruk adalah pelabuhan Utsmani yang paling dekat dengan perbatasan Mesir; jatuhnya membuka sayap timur Barqa dan memudahkan pasukan Italia berbaris ke barat menyusuri pantai.", "fa489107"]},
"OLAYLAR_EK9:1911-10-09:0":{"b": ["Menyerahnya kota Tripoli kepada Italia", "785091ad"], "d": ["Tripoli menyerah pada 9 Oktober 1911 setelah dibombardir tiga hari. Pasukan Utsmani memilih mundur ke Aziziya dan Gharyan untuk mengorganisasi perlawanan di pedalaman alih-alih mempertahankan kota; perlawanan yang diikuti Enver dan Mustafa Kemal Bey ini mengurung Italia di jalur pantai hingga akhir perang. Jadi, meskipun kota jatuh, pedalaman provinsi tetap berada di bawah kendali Utsmani.", "7deeaf70"]},
"OLAYLAR_EK9:1911-10-16:0":{"b": ["Lepasnya Derna akibat pendaratan Italia", "f014c741"], "d": ["Setelah Tobruk, giliran Derna, pelabuhan kedua Barqa; kota itu diduduki pada 16 Oktober 1911. Dataran tinggi di sekitar Derna adalah kawasan dengan kepadatan tarekat Sanusiyah tertinggi, dan para mujahid yang berhimpun atas seruan jihad Syekh Ahmed Syarif menahan Italia terkepung di sekitar pelabuhan. Pendudukan tetap terbatas pada kota dan tidak pernah meluas ke pedalaman.", "b6ada646"]},
"OLAYLAR_EK9:1911-10-21:0":{"b": ["Pendaratan Italia di Benghazi — hilangnya pusat sancak Barqa", "f9183c40"], "d": ["Benghazi, pusat Barqa, diduduki pada 21 Oktober 1911 lewat pendaratan keempat dan terpenting di pantai. Dengan demikian, tiga pekan setelah pernyataan perang, Italia menguasai semua pelabuhan besar provinsi Tripolitania (Tripoli, Tobruk, Derna, Benghazi), tetapi tidak berhasil memasuki pedalaman dari satu pun. Sisa satu tahun perang berlalu dengan serangan-serangan tanpa hasil dari keempat titik pantai itu ke arah dalam.", "6181e67f"]},
"OLAYLAR_EK9:1911-11-05:0":{"b": ["Dekret aneksasi sepihak Italia", "cfe3f9c2"], "d": ["Saat perang masih berlangsung, Italia pada 5 November 1911 mengeluarkan dekret yang menyatakan telah mencaplok Tripolitania dan Barqa. Kesultanan Utsmani tidak mengakuinya dan perang berlanjut setahun lagi; aneksasi baru memperoleh keabsahan hukum melalui Perjanjian Ouchy 18 Oktober 1912. Karena itu dekret ini tidak mengubah warna Utsmani di peta — kepemilikan hukum tetap pada Utsmani hingga 1912, dan kendali Italia ditampilkan sebagai pendudukan yang diarsir.", "23668758"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Direbutnya Köprühisar dan persiapan pendirian Yenişehir", "39abff03"], "d": ["Dengan jatuhnya benteng-benteng lintasan antara Bursa dan İznik, diletakkan dasar markas depan yang akan mengepung kedua kota.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Pendirian Yenişehir", "d3275837"], "d": ["Permukiman garnisun Utsmaniyah reguler pertama didirikan untuk mengelola pengepungan Bursa dan İznik; Orhan Gazi lahir di sini.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Pengepungan pertama İznik dan penaklukan Marmaracık", "cdca2349"], "d": ["İznik untuk pertama kalinya dikepung tetapi tidak dapat direbut (penaklukan definitif 1331); benteng Marmaracık di dekatnya direbut pada saat itu.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Ekspedisi pasukan Katalan ke Anatolia", "4fd940d5"], "d": ["Kompi Katalan yang disewa Bizantium untuk menghentikan kemajuan Turki meraih keberhasilan sementara tetapi tidak bertahan; dengan penarikan mereka, kemajuan beylik-beylik uç dipercepat.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal masuk Islam dan bergabung dengan Utsmaniyah", "ca0d86e1"], "d": ["Köse Mihal, tekfur Harmankaya, memeluk Islam dan bergabung dengan Osman Gazi bersama bentengnya dan anak buahnya; ia menjadi komandan Utsmaniyah asal Bizantium yang pertama.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Bey mengambil alih pemerintahan secara de facto", "6dadbefc"], "d": ["Karena usia lanjut dan sakitnya Osman Gazi, komando dan pengelolaan de facto pengepungan Bursa dan ekspedisi-ekspedisi beralih kepada putranya Orhan Bey (naik takhta secara resmi pada 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Direbutnya Mudanya", "0a623368"], "d": ["Mudanya, pelabuhan Bursa, direbut sehingga hubungan kota dengan laut terputus; pengepungan Bursa memasuki tahap pencekikan.", "c13020d5"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Penaklukan Akyazı dan Pulau İmralı", "d041b0c8"], "d": ["Akyazı di utara Sakarya direbut; dengan direbutnya Pulau İmralı, Utsmaniyah untuk pertama kalinya bertetangga dengan Pulau Marmara.", "591424a4"]},
"OLAYLAR_EK:1324-03-01:0":{"b": ["Penaklukan Gemlik (Kios) dan Armutlu", "682d3bac"], "d": ["Hubungan laut terakhir Bursa pun diputus sehingga kota itu disiapkan untuk menyerah pada 1326.", "c2b80b4a"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koca merebut Kandıra dan sekitarnya", "341bb97e"], "d": ["Akça Koca, salah satu uç beyi Orhan Gazi, ketika menyerbu wilayah İzmit dari markasnya di barat Danau Sapanca, merebut Kandıra dan sekitarnya menjelang 1326. İzmit masih di tangan Bizantium; kota itu baru akan jatuh pada 1337.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["Bergabungnya Yalova dan Karamürsel", "133cb07a"], "d": ["Yalova dan sekitarnya di pesisir selatan Teluk İzmit jatuh ke tangan Turki pada tahun ini; jalur pesisir diberikan oleh Orhan Bey kepada Karamürsel Gazi sebagai timar.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koca merebut Aydos dan benteng Samandıra", "ce4daa8a"], "d": ["Setelah direbutnya Kandıra, Akça Koca bersama Konuralp dan Gazi Abdurrahman merebut benteng Aydos di sekitar Kartal, lalu benteng Samandıra di utaranya; wilayah Samandıra diberikan kepadanya sebagai milik. Akça Koca wafat di dekat Kandıra pada 1328; wilayah uç beylik itu diberikan kepada Şehzade Murad.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Aliansi Utsmaniyah-Aydın-Saruhan", "9df6bb74"], "d": ["Tiga beylik bergerak bersama melawan Bizantium; armada Umur Bey dari Aydınoğulları melelahkan Bizantium di front kedua dengan serbuannya ke pesisir Thrakia.", "32ca49ea"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Pernikahan Orhan Gazi – Theodora: aliansi Bizantium", "9b67a590"], "d": ["Orhan Gazi, yang mendukung Kantakouzenos dalam perebutan takhta Bizantium, menikahi putrinya Theodora; aliansi ini memungkinkan pasukan Utsmaniyah mengenal Rumelia dari dekat.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Direbutnya Ankara", "49bf1f6d"], "d": ["Ankara, yang diperintah para ahi, masuk ke pemerintahan Utsmaniyah; jalan Anatolia Tengah terbuka. Tempat-tempat lain yang bergabung pada tanggal yang sama: Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Kemajuan di Thrakia pada masa Süleyman Paşa: Malkara, İpsala, dan Tekirdağ", "fb31cf02"], "d": ["Setelah kepala jembatan di Gelibolu didirikan, Süleyman Paşa maju ke utara dari semenanjung dan merebut dataran antara pesisir Marmara dan muara Maritsa selangkah demi selangkah. Malkara, İpsala, dan Rodosçuk (Tekirdağ) dengan demikian membentuk koridor tak terputus yang menghubungkan Gelibolu dan lembah Maritsa. Tanpa koridor ini tidak mungkin berbaris ke Edirne; kemajuan yang terhenti dengan wafatnya sang şehzade secara mendadak pada 1357 akan dilanjutkan oleh Lala Şahin dan Hacı İlbey.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Penculikan Şehzade Halil", "b52ac3d7"], "d": ["Halil, putra bungsu Orhan Gazi, diculik oleh bajak laut Foça; krisis tebusan menyibukkan hubungan Utsmaniyah-Bizantium selama bertahun-tahun.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Terputusnya jalur bantuan Edirne: benteng Çorlu, Lüleburgaz, Babaeski, dan Keşan", "8e8ad485"], "d": ["Şehzade Murad, yang kembali memulai operasi penaklukan setelah Halil diselamatkan, mengirim para akıncı hingga depan Istanbul untuk mengisolasi Edirne dari bantuan luar. Benteng Çorlu, Lüleburgaz, dan Babaeski di jalan Istanbul-Edirne serta Keşan di persimpangan jalan Thrakia Selatan direbut. Penyerahan Edirne datang setelah lingkaran pengepungan ini lengkap.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Direbutnya Dimetoka — terbukanya lembah Maritsa", "b59aee83"], "d": ["Dimetoka, benteng kunci lembah Maritsa, direbut; jalan menuju penaklukan Edirne pun terbuka. Berbaris ke Edirne tidak mungkin sebelum koridor yang membentang ke utara dari Gelibolu selesai; karena itu benteng ini dalam urutan penaklukan Rumelia mendahului Edirne. Kota itu untuk sementara menjadi markas Rumelia para sultan. Pasukan yang merebut Dimetoka kemudian, bersama benteng-benteng kecil seperti Kuleli Burgaz (Pythion), menguasai seluruh kawasan Maritsa Tengah.", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Hilangnya Gelibolu (Perang Salib Savoia)", "00e7e415"], "d": ["Armada Amadeus dari Savoia, sepupu kaisar Bizantium, merebut Gelibolu dan menyerahkannya kepada Bizantium; kepala jembatan Utsmaniyah di Rumelia dikelola dari seberang selat selama sepuluh tahun. Permukiman lain yang lepas pada tanggal yang sama: Çimpe.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Pertempuran Çirmen — kendali lembah Maritsa", "cd738d8d"], "d": ["Pasukan para bey Serbia dicerai-beraikan dalam serangan malam; para bey lokal Serbia/Bulgaria di Makedonia dan Rodopi satu per satu mulai membayar upeti kepada Utsmaniyah — bukan penaklukan langsung, melainkan awal gelombang vasalisasi. Dalam riwayat Utsmaniyah, pertempuran ini juga diceritakan dengan nama «Sırpsındığı» dan tahun 1364, sebagai serangan malam Hacı İlbey terhadap pasukan Salib yang datang merebut kembali Edirne; TDV menyatakan bahwa tanggal itu keliru dan kedua kisah itu mengenai pertempuran yang sama.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Penaklukan Filibe dan Eski Zağra", "e780c9ae"], "d": ["Filibe (Plovdiv) di hulu lembah Maritsa dan Eski Zağra (Stara Zagora) di utaranya direbut; kekaisaran Bulgaria diikat dengan upeti. Jalur Tatarpazarcığı dan İhtiman antara Filibe dan Sofia tetap di tangan para bey lokal yang menjadi vasal setelah Çirmen.", "b8131db8"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Bizantium vasal: Yohanes V dalam pasukan Murad I (akibat kemenangan Çirmen 1371)", "13ffe568"], "d": ["Menurut TDV, setelah kemenangan Çirmen (Maritsa) pada 26 September 1371, Kekaisaran Bizantium mengakui kekuasaan Utsmaniyah dan menjadi negara vasal dengan menerima kewajiban membayar upeti dan berdinas dalam pasukan Utsmaniyah. Dengan kewajiban ini Kaisar Yohanes V bergabung dengan pasukan Murad I pada 1373; putranya Andronikos IV, yang ia tinggalkan di Istanbul pada saat itu, memberontak melawan ayahnya bersama Şehzade Savcı Bey di Bursa.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Direbutnya kembali Gelibolu", "5f96c0a5"], "d": ["Andronikos IV, yang memperoleh dukungan Utsmaniyah dalam perebutan takhta Bizantium, sebagai imbalannya mengembalikan Gelibolu; jembatan antara Rumelia dan Anatolia dibangun kembali. Tempat-tempat lain yang bergabung pada tanggal yang sama: Çimpe.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Mas kawin Germiyan: bergabungnya Kütahya", "d6a6fe61"], "d": ["Dalam pernikahan Devletşah Hatun, putri Germiyanoğlu Süleyman Şah, dengan Yıldırım Bayezid, Kütahya, Simav, Tavşanlı, dan Eğrigöz beralih ke Utsmaniyah sebagai mas kawin — contoh klasik ekspansi tanpa perang. Tempat-tempat lain yang bergabung pada tanggal yang sama: Afyon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Pembelian wilayah Hamîd: bergabungnya Isparta", "4a1b6047"], "d": ["Hamîdoğlu Hüseyin Bey menjual sebagian beyliknya (Akşehir-Beyşehir-Isparta) kepada Murad I dengan imbalan uang tunai; sisa wilayah Hamid akan dianeksasi oleh Yıldırım pada 1391.", "d316dea5"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Penaklukan Serez", "d4d28b60"], "d": ["Serez, kunci Makedonia Timur, direbut; Selanik masuk lingkaran pengepungan. Garis Köstendil-Petriç-Nevrokop-Drama antara Sofia dan Serez belum bergabung langsung pada tanggal ini; secara berurutan menjadi vasal antara 1370-an dan 1383, dan di bawah pemerintahan langsung setelah 1383.", "573cc19c"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Penaklukan Sofia", "96d5f01f"], "d": ["Lintasan barat Pegunungan Balkan dibawa ke bawah kendali; karena Serez sudah dikuasai sejak 1383, wilayah Thrakia-Makedonia pada tanggal ini membentuk satu kesatuan tak terputus.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Penaklukan Niš", "77f5d632"], "d": ["Dengan direbutnya Niš, kunci lembah Morava, despotat Serbia terancam secara langsung.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Penyerahan pertama Selanik", "96010ee9"], "d": ["Setelah blokade panjang, kota itu menyerah (pada 1403 akan dikembalikan kepada Bizantium, dan pada 1430 ditaklukkan secara definitif). Tempat-tempat lain yang bergabung pada tanggal yang sama: Kavala.", "5ef8bffd"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Ahidname Utsmaniyah-Genoa — pembaruan perjanjian 1352", "be11d17a"], "d": ["Dengan para utusan Genoa dari Pera, perjanjian dagang 1352 peninggalan masa Orhan Gazi diperbarui; pajak antara kedua negara, perlakuan terhadap tawanan, dan perdagangan bebas ditetapkan kembali. Ini dianggap ahidname persahabatan dan perdagangan pertama yang diketahui secara resmi antara Utsmaniyah dan Genoa — bukan aliansi militer, melainkan perjanjian yang sepenuhnya bersifat dagang.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Ekspedisi Çandarlı Ali Paşa ke Bulgaria: direbutnya Şumnu dan Rusçuk", "2781c3a9"], "d": ["Benteng-benteng Kekaisaran Bulgaria di sepanjang Danube diambil dalam satu ekspedisi; jangan dikacaukan dengan kekalahan di Bileça di Bosnia pada tahun yang sama — itu adalah keberhasilan serentak di front terpisah. Tırnova dan Vidin masih merupakan pusat Bulgaria terakhir yang bertahan.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Kekalahan Bileća", "89ba0a64"], "d": ["Pasukan akıncı yang bergerak ke Bosnia disergap dan dimusnahkan di Bileća; kemunduran besar pertama di Balkan ini membesarkan hati aliansi yang menuju Kosovo.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Aneksasi beylik-beylik Anatolia Barat: Saruhan, Aydın, Menteşe", "dcc33b71"], "d": ["Tiga beylik bergabung dalam satu ekspedisi: Manisa, pusat Saruhanoğulları; Aydın, pusat Aydınoğulları (termasuk benteng Atas İzmir, tetapi pelabuhan/benteng bawah masih di tangan Ksatria St. Jean — hingga 1402); Muğla-Milas, pusat Menteşeoğulları, termasuk jalur pesisir Datça-Bodrum-Marmaris-Fethiye. Pesisir Aegea untuk pertama kalinya bersatu di satu tangan. Tempat-tempat lain yang bergabung pada tanggal yang sama: Söke.", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Aneksasi wilayah Teke: bergabungnya Antalya", "fdbeee5c"], "d": ["Wilayah Teke di pesisir Mediterania bergabung ke wilayah Utsmaniyah. Tekeoğulları adalah cabang yang memisah dari Hamîdoğulları: Feleküddin Dündar Bey menyerahkan Antalya yang ditaklukkannya kepada saudaranya Yûnus Bey, dan sekitar 1321 lahirlah sebuah beylik tersendiri. Karena itu Antalya dan sekitarnya di peta setelah 1321 ditampilkan dengan warna Tekeoğulları, bukan Hamîdoğulları. Beylik ini didirikan kembali setelah Perang Ankara dan baru dilikuidasi secara definitif pada 1423.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Penaklukan Üsküp", "9e5a1af5"], "d": ["Pusat Makedonia Vardar direbut; Üsküp menjadi salah satu pusat uç utama Rumelia.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Aneksasi Kastamonu", "876330ba"], "d": ["Cabang Kastamonu dari Candaroğulları dilikuidasi; cabang Sinop berlanjut sebagai vasal. Tempat-tempat lain yang bergabung pada tanggal yang sama: Bartın, Safranbolu.", "34d8e600"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Jatuhnya Tırnova — aneksasi Bulgaria", "ff666977"], "d": ["Ibu kota kekaisaran Bulgaria jatuh; Bulgaria masuk ke pemerintahan langsung Utsmaniyah. Tempat-tempat lain yang bergabung pada tanggal yang sama: Plevne, Lofça.", "182028e2"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["Benteng Lofça (Lovech) beralih ke Utsmaniyah", "a55e87a0"], "d": ["Lofça, salah satu benteng Tsar Bulgaria İvan Şişman, bergabung ke wilayah Utsmaniyah bersama provinsi-provinsi Şişman lainnya dalam ekspedisi 1393 ketika Tırnova jatuh. Sumber tidak tegas: penaklukan itu «diperkirakan» terjadi pada tahun ini.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Bergabungnya Dobruja", "478e36f2"], "d": ["Wilayah Dobruja yang membentang hingga delta Danube bergabung. Tempat-tempat lain yang bergabung pada tanggal yang sama: Silistre, Köstence.", "05bdabb4"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Turunnya ke Thessalia", "8bec60dd"], "d": ["Dataran Thessalia yang berpusat di Yenişehir (Larissa) dibawa ke bawah pemerintahan Utsmaniyah. Tempat-tempat lain yang bergabung pada tanggal yang sama: Tırhala, İzdin (Lamia).", "d9f2128c"]},
"OLAYLAR_EK:1394-01-01:1":{"b": ["Pengepungan ketat Istanbul dimulai (blokade sejak ~1387)", "0068bc04"], "d": ["Yıldırım Bayezid menahan Istanbul dalam blokade berselang selama sepuluh tahun; kota itu baru selamat berkat mendekatnya Timur.", "504fcb33"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["Pertempuran Rovine — ekspedisi Wallachia", "343ae7a9"], "d": ["Setelah pertempuran berdarah dengan voivode Wallachia Mircea yang hasilnya diperdebatkan, Wallachia setuju membayar upeti kepada Utsmaniyah; tatanan vasalase di utara Danube pun terbentuk.", "dd69200f"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Penaklukan Nikopolis", "b9791717"], "d": ["Setelah Pertempuran Rovine 1395 melawan Wallachia, Yıldırım Bayezid merebut benteng Nikopolis di tepi Danube; sebagian kronik anonim Bulgaria menyatakan penaklukan terjadi pada 3 Juni 1395. Tanggal penaklukan tidak tunggal dalam sumber-sumber: entri Pertempuran Nikopolis dalam TDV İslâm Ansiklopedisi menulis bahwa Bayezid merebut Silistre dan Nikopolis dalam ekspedisi Danube tahun 1394. Benteng itu akan dikepung dalam Perang Salib terkenal 1396, tetapi tidak jatuh. Tempat-tempat lain yang bergabung pada tanggal yang sama: Ohri.", "bc450a9f"]},
"OLAYLAR_EK:1395-06-03:0":{"b": ["Benteng Nikopolis beralih ke Utsmaniyah", "327012c9"], "d": ["Setelah serbuan Rovine, Yıldırım Bayezid merebut Nikopolis; Tsar Bulgaria İvan Şişman, yang menetap di sana sebagai vasal Utsmaniyah, disingkirkan. Dalam atlas Nikopolis dicatat beralih dari Kekaisaran Bulgaria ke Utsmaniyah pada hari ini.", "6e7d5207"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Pembangunan Anadolu Hisarı", "aa259b00"], "d": ["Untuk mendukung blokade Istanbul, Güzelcehisar (Anadolu Hisarı) dibangun di sisi Anatolia Selat — langkah permanen pertama kendali atas selat.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Aneksasi Vidin", "ee1ae44b"], "d": ["Setelah kemenangan Nikopolis, kepangeranan Bulgaria terakhir, Vidin, juga dianeksasi.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Aneksasi pertama Karaman", "3cf07876"], "d": ["Dengan kemenangan Akçay, wilayah Karamanoğlu untuk pertama kalinya bergabung dengan Utsmaniyah (akan didirikan kembali pada Masa Fetret).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Bergabungnya pesisir Canik: Samsun", "af9c40fa"], "d": ["Dalam kekosongan yang muncul akibat tertawannya Kadı Burhâneddin oleh Karayülük Osman Bey dari Akkoyunlu, Yıldırım Bayezid lebih dulu mengikat wilayah Canik di pesisir Laut Hitam ke pemerintahan Utsmaniyah. Samsun dan sekitarnya dengan demikian menjadi pelabuhan Laut Hitam pertama bagi dinasti. Garis Sivas-Tokat-Kayseri di pedalaman akan bergabung dua minggu kemudian, dengan terurainya Negara Kadı Burhâneddin secara de facto.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Direbutnya Malatya", "7cb6ae16"], "d": ["Malatya di perbatasan Mamluk direbut — salah satu langkah yang meningkatkan ketegangan dengan Timur.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Timur merebut Malatya dan menyerahkannya kepada Karayülük Osman — setelah Timur mundur, Dulkadıroğulları merebutnya kembali", "ad2ce7d8"], "d": ["Yıldırım Bayezid, setelah merebut Malatya pada 1399, menyerahkannya kepada Dulkadıroğlu Nasreddin Mehmed dan kembali ke Bursa. Timur, yang memasuki Anatolia pada 1400, merebut lebih dulu Sivas dan Elbistan, lalu Malatya; kota dan sekitarnya dijarah dan pengelolaannya diserahkan kepada Karayülük Osman yang bersama Timur. Setelah Timur meninggalkan wilayah itu, Dulkadıroğulları kembali menguasai Malatya; dengan demikian kekuasaan Utsmaniyah berakhir sebelum Ankara.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Süleyman Çelebi – perjanjian dengan Bizantium: pengembalian Selanik", "cc503cc2"], "d": ["Süleyman Çelebi, yang menguasai Rumelia pada masa Fetret, bersepakat dengan Bizantium dan negara-negara Latin dan menyerahkan Selanik serta pesisir Laut Hitam hingga Misivri kepada Bizantium (TDV fetret-devri: Perjanjian Gelibolu, Februari 1403) — di peta İğneada, Rezve, dan Ahtapolu beralih ke Bizantium; di peta Selanik keluar dari Utsmaniyah pada tanggal ini.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Kekalahan laut Gelibolu (Venesia)", "b71d4d68"], "d": ["Armada Venesia mengalahkan armada Utsmaniyah secara telak di depan Gelibolu; peristiwa ini menunjukkan batas-batas pelayaran Utsmaniyah masa awal.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Pemberontakan Düzmece Mustafa", "0ec43138"], "d": ["Mustafa Çelebi, yang mengaku putra Yıldırım, memproklamasikan kesultanan di Rumelia dengan dukungan Bizantium; Murad II menumpas pemberontakan itu pada 1422 dan mengeksekusi saingannya.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Pengepungan Istanbul oleh Murad II", "4b9d9fba"], "d": ["Sebagai balasan atas dukungan Bizantium kepada Düzmece Mustafa, Murad II mengepung Istanbul; pengepungan dicabut ketika saudaranya Küçük Mustafa dibangkitkan untuk memberontak di Anatolia.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Penyerahan Selanik kepada Venesia", "bfa6c4a0"], "d": ["Gubernur Bizantium di bawah tekanan Utsmaniyah menyerahkan kota kepada Venesia; persaingan Utsmaniyah-Venesia yang akan berlangsung tujuh tahun pun dimulai.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Aneksasi kembali beylik-beylik Anatolia Barat: Menteşe dan Aydın", "aca30a48"], "d": ["Dua beylik Aegea yang didirikan kembali pada Masa Fetret dimasukkan secara definitif ke wilayah Utsmaniyah pada masa Murad II. Menurut entri Menteşeoğulları di TDV, Murad II merebut wilayah Menteşe pada 827 (1424) dan memenjarakan dua saudara yang memimpin beylik. Menurut entri Aydınoğulları, Beylerbeyi Anatolia Hamza Bey menangkap Cüneyd Bey yang kembali membangkang dan mengeksekusinya bersama keluarganya (829/1425-26), dan wilayah Aydın beralih ke Utsmaniyah. Ksatria St. Jean, yang memegang benteng pelabuhan İzmir sejak 1344, kehilangannya kepada Timur pada 1402 dan wilayah itu kembali ke kendali Aydınoğlu; dengan aneksasi ini wilayah itu pun bergabung ke Utsmaniyah. Wilayah Teke (Antalya) bukan pokok entri ini: Tekeoğulları telah dilikuidasi tersendiri pada 1423. Germiyan akan bergabung pada 1429 dengan wasiat.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Aneksasi Germiyan dengan wasiat", "9eb86b77"], "d": ["Bey Germiyan, Yakub II, yang wafat tanpa anak, mewariskan negerinya kepada Utsmaniyah melalui wasiat — contoh aneksasi tanpa perang yang masuk buku pelajaran. Tempat-tempat lain yang bergabung pada tanggal yang sama: Karahisâr-ı Sâhib (Afyon).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Penaklukan definitif Selanik", "bc021768"], "d": ["Kota yang berada di bawah pemerintahan Venesia itu direbut dengan serbuan; pelabuhan besar kedua Rumelia menjadi Utsmaniyah secara pasti. Tempat-tempat lain yang bergabung pada tanggal yang sama: Kesendire (Kassandra).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Penyerahan Yanya", "ee45cb52"], "d": ["Yanya (Ioannina), pusat Epirus, menyerah dengan perjanjian.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Direbutnya Semendire yang pertama", "c11ca17d"], "d": ["Ibu kota despotat Serbia direbut melalui pengepungan tiga bulan dan Serbia untuk pertama kalinya dianeksasi (akan dikembalikan dengan Perjanjian Edirne-Szeged 1444).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Pengepungan Beograd (gagal)", "3e05f425"], "d": ["Pengepungan besar pertama Beograd yang berlangsung enam bulan tidak membuahkan hasil; benteng itu tetap menjadi kunci penghalang kemajuan Utsmaniyah selama delapan puluh tahun.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Kekalahan Zlatica — 'Ekspedisi Panjang'", "97df1466"], "d": ["Pasukan yang dibawa Hunyadi ke Balkan di tengah musim dingin melewati Niš dan Sofia hingga mencapai Zlatica; pertahanan Utsmaniyah nyaris tidak bertahan. Suasana kekalahan ini membawa perdamaian Edirne-Szeged ke meja perundingan.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Perjanjian Edirne-Szeged", "0aa4e0de"], "d": ["Perdamaian sepuluh tahun: despotat Serbia dikembalikan, Danube diterima sebagai perbatasan. Pelanggaran perjanjian dalam hitungan bulan atas hasutan Paus membawa pada bencana Varna.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Pengembalian Semendire dan benteng-benteng Serbia kepada Serbia", "cda3cf9e"], "d": ["Ketentuan Perjanjian Edirne-Szeged dilaksanakan: pada 15 Agustus 1444 Murad II mengembalikan Semendire bersama dua puluh empat bentengnya yang penting dan wilayah Serbia lain yang diduduki kepada Đurađ Branković (TDV semendire); Niš (TDV nis), Alacahisar (TDV alacahisar), Şehirköy (TDV sehirkoy), dan Priştine (TDV pristine) juga diserahkan kepada Serbia. Vidin tidak termasuk pengembalian karena bukan wilayah Serbia — itulah sumber kehilangan wilayah barat laut yang terlihat di sekitar kemenangan Varna; beberapa bulan kemudian perjanjian itu sendiri sudah batal dengan kekalahan Varna.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Rumeli Hisarı selesai — 'Pemotong Selat'", "480e8a76"], "d": ["Dengan benteng yang selesai dalam pembangunan luar biasa cepat yang menurut sumber berlangsung empat lima bulan, kendali Selat sepenuhnya beralih ke Utsmaniyah; jalur bantuan dari Laut Hitam ke Istanbul tertutup. Dianggap langkah nyata pertama pengepungan.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Pengepungan Istanbul dimulai", "8af50742"], "d": ["Pasukan menempati posisi di depan tembok; dalam pengepungan yang akan berlangsung 54 hari, meriam raksasa untuk pertama kalinya digunakan secara sistematis terhadap tembok sebuah ibu kota.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Kapal-kapal diturunkan ke Tanduk Emas melalui darat", "4f2ba07c"], "d": ["Sekitar 70 kapal dari armada yang tidak dapat memasuki Tanduk Emas yang ditutup rantai diseret melintasi punggung bukit Galata dengan luncuran berminyak dan diturunkan ke Tanduk Emas dalam satu malam; pertahanan terbagi menjadi dua front.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Penaklukan Athena", "4f0f1bb2"], "d": ["Kadipaten Athena berakhir; panji Utsmaniyah dikibarkan di Akropolis. Tempat-tempat lain yang bergabung pada tanggal yang sama: İstefe (Thebai), Livadya.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Aneksasi Serbia (jatuhnya Semendire)", "75fd0a62"], "d": ["Semendire, ibu kota despotat Serbia, menyerah; Serbia menjadi sebuah sancak Utsmaniyah.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Penaklukan Mora", "7d5a3c18"], "d": ["Despotat Mora dilikuidasi; semenanjung (kecuali benteng-benteng Venesia) masuk ke pemerintahan Utsmaniyah.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Bergabungnya Sinop", "e03c2739"], "d": ["Candaroğlu menyerahkan Sinop tanpa perang; jalan ke ekspedisi Trabzon terbuka. Tempat-tempat lain yang bergabung pada tanggal yang sama: Kastamonu, Bartın, Safranbolu. Entri Candaroğulları di TDV juga menyebut Bolu, Eflani, dan Tosya di antara wilayah beylik Candaroğlu yang dianeksasi pada 1461; dalam atlas ketiga tempat ini juga dicatat beralih dari Candaroğlu ke Utsmaniyah pada hari ini.", "4ef62060"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Runtuhnya Kerajaan Bosnia — ekspedisi Bosnia Fâtih", "5362e3f2"], "d": ["Ketika raja Bosnia terakhir Stjepan Tomašević (1461-1463) menolak membayar upeti dengan bersandar pada dukungan Barat, ia dianggap tidak lagi menjadi penguasa vasal, dan pasukan di bawah Sultan Mehmed Fâtih melikuidasi Kerajaan Bosnia dalam satu ekspedisi. Raja ditangkap dan dieksekusi, kerajaan lenyap, dan sancak Bosnia didirikan di wilayah itu. Namun runtuhnya kerajaan tidak sama dengan penaklukan Bosnia. Pemerintahan Utsmaniyah sudah ada di dataran itu selama lima belas tahun — Hodidjed dan dataran Saray diambil pada 1448, uç beylik Îsâ Bey didirikan di tengah kerajaan. Penaklukan tidak selesai pada 1463: Foça pada 1465, Livno pada 1469, Kadipaten Herzegovina pada 1483, banovina Srebrenik pada 1512, sedangkan Yayça dan Banja Luka di utara baru dapat direbut pada 1528 setelah Mohács — orang Hongaria setelah 1463 mendirikan sebuah banovina yang bertahan enam puluh lima tahun di utara Bosnia. Tempat yang berpindah tangan secara langsung pada tanggal ini adalah Travnik; Yayça pada tanggal ini beralih bukan ke Utsmaniyah melainkan ke Hongaria.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Aneksasi definitif Karaman", "f1dcecaa"], "d": ["Wilayah inti Karamanoğulları bergabung secara definitif; pertikaian internal berlanjut hingga 1470-an. Tempat-tempat lain yang bergabung pada tanggal yang sama: Niğde, Mostar, Beyşehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Penaklukan Eğriboz", "5c97daf3"], "d": ["Eğriboz (Negroponte), pangkalan utama Venesia di Aegea, jatuh.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Aneksasi Alanya, Anamur, dan Silifke (İçel)", "a0b9d461"], "d": ["Jalur pesisir İçel yang terikat pada Karamanoğulları (seluruh Mediterania antara Antalya dan Mersin) bergabung melalui ekspedisi laut Gedik Ahmed Paşa; Alanya penting dengan galangan strategisnya peninggalan masa Seljuk.", "8302df58"]},
"OLAYLAR_EK:1478-01-15:0":{"b": ["Aneksasi Novgorod oleh Moskow", "bed87170"], "d": ["Adipati Agung Ivan III menurunkan lonceng simbolis majelis rakyat (veche) di Novgorod, mengganti para pejabat lokal dengan gubernurnya sendiri, dan secara de facto mengikat kota itu ke Moskow; Novgorod tidak lagi menjadi republik merdeka. Wilayah Novgorod membentang dari Laut Baltik hingga Laut Putih dan Pegunungan Ural. Dalam atlas Novgorod dicatat beralih dari Republik Novgorod ke Moskow pada hari ini.", "65b660e7"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Perjanjian Istanbul — Albania dan İşkodra", "b09652f7"], "d": ["Perang Utsmaniyah-Venesia selama 16 tahun berakhir; İşkodra dan pesisir Albania tetap di tangan Utsmaniyah. Tempat-tempat lain yang bergabung pada tanggal yang sama: Limni, Sisam, Bozbaba (Ay Strati).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Pendaratan di Otranto", "7916b89d"], "d": ["Pasukan Utsmaniyah yang mendarat di pesisir Apulia (Pulya) mengepung dan merebut benteng Otranto; karena kota dimasuki dengan pertempuran, sebagian tokoh yang melawan dieksekusi dan sebagian ditawan. Tradisi gereja mengenang yang tewas sebagai sekitar 800 'syuhada Otranto'; TDV mengaitkan pembesaran angka ini dengan propaganda gereja. Hanya benteng di ujung semenanjung Salento dan lingkungan sempitnya yang dikuasai; wilayah Kerajaan Napoli lainnya di garis Taranto-Brindisi-Lecce tidak lepas — kepala jembatan menuju Italia ini akan bertahan satu tahun.", "0e1004b8"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Pengosongan Otranto", "37371bb0"], "d": ["Dengan wafatnya Sultan Mehmed Fâtih (3 Mei 1481), garnisun Otranto yang tidak lagi berharap bala bantuan baru mengosongkan benteng melalui kesepakatan di hadapan pengepungan putra mahkota Napoli Alfonso; kepala jembatan Utsmaniyah satu-satunya di Italia itu pun hilang setahun kemudian.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Penaklukan Modon dan Koron", "38b608c4"], "d": ["Modon dan Koron, 'dua mata' Venesia di Mora, direbut.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Penaklukan Durrës", "1f231b98"], "d": ["Selama perang Utsmaniyah-Venesia 1499-1503, pasukan di bawah komando Mehmed Bey merebut Durrës, pelabuhan besar Albania terakhir Venesia di Adriatik. Setelah İşkodra (1479) dan Vlora (1417), dengan penaklukan ini jalur pesisir Albania seluruhnya masuk ke kendali Utsmaniyah.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Bergabungnya Anatolia Timur", "e0cb8f8f"], "d": ["Setelah Çaldıran, Diyarbakır dan sekitarnya bergabung; beylik-beylik Kurdi diikat kepada Utsmaniyah melalui İdrîs-i Bitlisî.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Penaklukan Benteng Varadin (Petrovaradin)", "abf392a5"], "d": ["Pasukan yang berangkat dalam ekspedisi Mohács menyeberang dari Beograd ke tanah Hongaria; lebih dulu pinggiran luar Varadin direbut, kemudian benteng jatuh setelah pengepungan empat belas hari. Kanuni memerintahkan agar desa-desa di jalan tidak dibakar, karena tempat-tempat itu kini dianggap tanah Utsmaniyah.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Penyerahan Buda setelah Mohács — dua raja untuk takhta Hongaria", "9d3568a0"], "d": ["Kunci-kunci kota diserahkan kepada sultan pada 11 September 1526 ketika pasukan Utsmaniyah yang berbaris ke Buda setelah kemenangan Mohács tiba; namun Kanuni tidak mempertahankan Buda dan menarik pasukannya. Di Hongaria yang tanpa raja, para bangsawan memilih dua raja berbeda: János Szapolyai pada 10 November 1526, dan Ferdinand I dari Habsburg pada 17 Desember 1526. Ferdinand merebut Buda pada Agustus 1527. Menetapnya Szapolyai di Buda sebagai raja di bawah perlindungan Utsmaniyah akan terjadi dengan ekspedisi 1529 (lihat entri 1529), dan pemerintahan langsung Utsmaniyah akan didirikan pada 1541.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["János Szapolyai dipilih sebagai raja Hongaria — Utsmaniyah mengakui kerajaannya dengan syarat menjadi vasal", "32bc6baf"], "d": ["Sebagian bangsawan memilih János Szapolyai, voivode Transilvania, untuk takhta Hongaria yang kosong karena wafatnya raja di Mohács; Szapolyai dimahkotai di Székesfehérvár. Utsmaniyah, yang mengosongkan Buda, mengakui kerajaan Szapolyai dengan syarat menjadi vasal mereka agar wilayah itu tetap menjadi penyangga. Di peta, tempat-tempat yang terikat pada Szapolyai tampak menjadi vasal Utsmaniyah sejak tanggal ini.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Ferdinand I dinyatakan raja Hongaria — Hongaria Barat dan Utara ke mahkota Habsburg", "b3910a2f"], "d": ["Archduke Habsburg Ferdinand, bersandar pada pernikahan saudara perempuannya dengan Lajos II, menuntut hak atas takhta Hongaria dan dinyatakan raja oleh sebagian bangsawan. Dengan demikian Hongaria terbagi antara dua raja; bagian barat dan utara mengakui Ferdinand. Para bangsawan Kroasia juga memilihnya secara terpisah pada awal 1527.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Pertikaian dua raja: Esztergom ke perlindungan Habsburg, Szeged ke Szapolyai", "da92dee5"], "d": ["Esztergom, yang berpindah tangan antara dua raja sejak 1526, masuk ke perlindungan Habsburg setelah uskup agung pindah ke utara dengan arsip dan perbendaharaannya. Dari tahun yang sama hingga 1541, Szeged tetap di bawah kedaulatan Szapolyai.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["Penduduk Pécs beralih ke pihak Szapolyai", "3fc4e7f2"], "d": ["Pécs, yang memperoleh imtiyaz dari Ferdinand pada 1528, tak lama kemudian beralih ke pihak Szapolyai; Raja János tinggal di kota untuk beberapa waktu pada 1533. Dengan jatuhnya Buda pada 1541, kota itu kembali ke pihak Ferdinand.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Penaklukan Tripoli", "8c659986"], "d": ["Tripoli direbut dari Ksatria Saint Jean; pesisir tengah Afrika Utara menjadi Utsmaniyah. Tempat-tempat lain yang bergabung pada tanggal yang sama: Misrata.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Penaklukan Timișoara", "e9fd4995"], "d": ["Wilayah Banat direbut dan Beylerbeylik Timișoara didirikan.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Penaklukan definitif Tunisia", "7bbd11bc"], "d": ["Tunisia, yang berada di bawah kendali Spanyol-Hafsiyah, masuk secara definitif ke pemerintahan Utsmaniyah; garis Afrika Utara pun lengkap. Tempat-tempat lain yang bergabung pada tanggal yang sama: Kayrevan, Gabes, Sfaks.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Penaklukan Kanije", "0c7b6aa3"], "d": ["Kanije direbut dalam Perang Panjang; pertahanan Tiryâki Hasan Paşa pada tahun berikutnya menjadi legenda.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Ekspedisi Uyvar dimulai — Fâzıl Ahmed Paşa berbaris dari Edirne menuju Austria", "306a86db"], "d": ["Ketika Austria menyerang Transilvania dan merebut benteng Székelyhíd dan Kolozsvár, Istanbul memutuskan ekspedisi melawan Habsburg. Wazir Agung Köprülüzâde Fâzıl Ahmed Paşa berangkat dari Edirne pada 13 April 1663. Di Beograd datang permintaan damai dari Austria, tetapi dalam dua pertemuan di Osijek syarat-syarat Utsmaniyah ditolak. Dalam musyawarah di Buda, sasaran pun ditetapkan Uyvar.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Penaklukan Uyvar", "ce289470"], "d": ["Uyvar (Nové Zámky), benteng kunci Hongaria Utara, direbut; ungkapan 'sekuat seorang Turki di depan Uyvar' masuk ke dalam bahasa-bahasa Eropa. Setelah Uyvar, Nitra dan Léva juga menyerah setelah perlawanan singkat; keduanya direbut kembali oleh De Souches pada musim semi 1664.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Direbutnya kembali Mora", "9b6460f1"], "d": ["Mora, yang diserahkan kepada Venesia di Karlowitz, direbut kembali dalam satu ekspedisi. Tempat-tempat lain yang bergabung pada tanggal yang sama: Balyabadra (Patras), İnebahtı.", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Kehilangan Beograd yang kedua — pengepungan Pangeran Eugen", "6a194354"], "d": ["Setelah kekalahan Varadin dan hilangnya Timișoara, Pangeran Eugen mengepung Beograd; ketika pasukan bantuan yang datang menyelamatkan kota juga dikalahkan, benteng menyerah. Kota yang telah direbut kembali pada 1690 setelah Karlowitz itu pun lepas lagi dan garis pertahanan Danube runtuh. Beograd baru dapat direbut kembali dua puluh dua tahun kemudian dengan Perjanjian Beograd 1739. Permukiman lain yang lepas pada tanggal yang sama: Semendire. Atlas juga mencatat wilayah Hisarcık (Grocka) dan Yagodina (Jagodina) untuk Habsburg pada hari ini (hari tingkat wilayah; hari tingkat tempat tidak ada dalam sumber, pendekatan yang dinyatakan); sedangkan Mehádia beralih ke Habsburg pada tanggal 27 Agustus 1717 (Bánlaky 0019/1715).", "83c63cd6"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Jatuhnya Özi", "90a67a6c"], "d": ["Özi (Ochakov), benteng kunci di utara Laut Hitam, jatuh ke tangan Rusia dalam serbuan berdarah; penduduk kota dibantai dengan pedang.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Perjanjian Bukares — hilangnya Bessarabia", "932da4d6"], "d": ["Dengan perjanjian yang mengakhiri perang Rusia 1806-1812, wilayah di timur Prut (Bessarabia) diserahkan kepada Rusia. Permukiman lain yang lepas pada tanggal yang sama: Akkirman, Kili, Hotin, Bender, İsmail. Atlas juga menganggap Kişinev (Chișinău), Bălți, Kahul (Cahul), dan Orhei di dalam Bessarabia telah beralih dari Moldavia (vasal Utsmaniyah) ke Rusia pada hari yang sama. Soroka (Soroca) juga beralih ke Rusia pada hari yang sama.", "b5921c60"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Perjanjian Edirne", "b3a8fe4c"], "d": ["Pada akhir perang ketika pasukan Rusia memasuki Edirne, delta Danube hilang; otonomi/kemerdekaan Yunani diakui secara de facto. Permukiman lain yang lepas pada tanggal yang sama: İbrail, Anapa, Ahıska. Meski perjanjian mengembalikan tanah, ia tidak segera mengakhiri pendudukan: Wallachia-Moldavia dan Silistre tetap berada di bawah administrasi Rusia sebagai jaminan sampai ganti rugi perang dibayar — itulah sebabnya di peta tempat-tempat ini tampak masih diduduki setelah 1829.", "d09a34fb"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Dekret otonomi untuk Serbia — knez turun-temurun dan syarat garnisun", "6a5d901d"], "d": ["Hatt-ı hümâyun yang dikeluarkan sesuai ketentuan Perjanjian Edirne tentang Serbia mengakui Miloš Obrenović sebagai knez turun-temurun dan menjadikan Serbia kepangeranan otonom yang bebas dalam urusan dalam negeri dan terikat pada Utsmaniyah dalam urusan luar. Ketentuannya: kedudukan knez diwariskan dari ayah ke anak, pajak tahunan dibayar tetap, majelis Serbia membentuk pemerintahan dalam negerinya sendiri, gereja otonom; sebagai imbalannya garnisun Utsmaniyah tetap berada di benteng Beograd, Semendire, Šabac, Böğürdelen, dan Fethülislâm. Struktur ganda ini bertahan hingga penarikan garnisun pada 1867. Di peta, kota Beograd pada tanggal ini bergabung ke Serbia otonom; benteng Kalemegdan ditampilkan di bawah garnisun Utsmaniyah hingga 1867.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Penyerahan Siprus ke administrasi Inggris", "423da3ee"], "d": ["Sebagai imbalan aliansi melawan ancaman Rusia, administrasi Siprus diserahkan kepada Inggris; secara hukum tetap wilayah Utsmaniyah. Permukiman lain yang lepas pada tanggal yang sama: Lefkoşa, Magosa, Girne, Limasol, Larnaka (Tuzla), Baf, Güzelyurt (Morphou), Akrotiri, Episkopi, Dikelya (Dhekelia); yakni seluruh pulau.", "d1abea1c"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Penyerahan Thessalia kepada Yunani", "ac614d24"], "d": ["Sesuai keputusan Kongres Berlin, Thessalia dan sekitar Narda diserahkan kepada Yunani. Permukiman lain yang lepas pada tanggal yang sama: Arta, Yenişehir (Larissa), Tırhala, İzdin (Lamia). Dengan penyerahan ini Golos (Volos), Kalabaka, dan Kardiçe (Thessalia) beralih ke Yunani.", "9fc28546"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Bergabungnya Rumelia Timur dengan Bulgaria", "ee43f137"], "d": ["Provinsi otonom Rumelia Timur dihubungkan dengan Bulgaria melalui kudeta; Bâbıâli menerima fait accompli itu. Dengan penyatuan ini seluruh Rumelia Timur (Eski Zağra, Tatarpazarcığı, İslimye, Hasköy, Burgaz, Aydos, Elhova) beralih ke Kepangeranan Bulgaria.", "7fe3cc42"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Pertempuran Domokos", "9c6f29a5"], "d": ["Dalam Perang Utsmaniyah-Yunani 1897, pasukan meraih kemenangan menentukan di Domokos; perolehan wilayah tetap terbatas karena tekanan diplomatik.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Otonomi untuk Kreta", "2e764881"], "d": ["Meski Perang Utsmaniyah-Yunani berakhir dengan kemenangan Utsmaniyah, Inggris, Rusia, Prancis, dan Italia pada 18 Desember 1897 mengumumkan otonomi Kreta; pulau itu akan menjadi provinsi netral dan otonom di bawah kedaulatan Utsmaniyah. Setelah 6 November 1898 bendera Turki tidak lagi dikibarkan di Kandiye dan Kisamo; dengan Pangeran George, putra raja Yunani, mulai bertugas sebagai komisaris luar biasa pada 22 Desember 1898, Kreta secara de facto keluar dari pemerintahan Utsmaniyah (secara resmi terpisah pada 1913). Permukiman lain yang lepas pada tanggal yang sama: Kandiye (Girit), Hanya.", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Kemerdekaan Bulgaria dan aneksasi Bosnia", "393feaa4"], "d": ["Dalam kekacauan Masa Konstitusional, Bulgaria memproklamasikan kemerdekaannya dan Austria-Hongaria menganeksasi Bosnia-Herzegovina. Dengan proklamasi ini seluruh wilayah Kepangeranan Bulgaria (Varna, Şumnu, Rusçuk, Burgaz, İslimye, dll.) menjadi Kerajaan Bulgaria yang merdeka.", "b7f0bb26"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Direbutnya kembali Edirne", "536e5599"], "d": ["Dalam Perang Balkan II, pasukan menyeberangi Maritsa dan merebut kembali Edirne tanpa perang. Tempat-tempat lain yang bergabung pada tanggal yang sama: Kırklareli, Tekirdağ.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Kemenangan Kut al-Amara", "98b972bc"], "d": ["Komandan divisi Inggris yang terkepung di Kut menyerah bersama 13 ribu prajuritnya — salah satu kemenangan Utsmaniyah terbesar dalam Perang Dunia I.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Hilangnya Baghdad", "2c18a816"], "d": ["Baghdad Utsmaniyah yang telah berusia 383 tahun beralih ke tentara Inggris. Permukiman lain yang lepas pada tanggal yang sama: Kerbelâ.", "4add66da"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Hilangnya Yerusalem", "94067617"], "d": ["Yerusalem Utsmaniyah yang telah berusia 401 tahun diserahkan tanpa dapat dipertahankan.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Hilangnya Damaskus", "ed177b68"], "d": ["Dengan runtuhnya front Palestina, Damaskus dikosongkan; pemerintahan Utsmaniyah empat abad di Suriah berakhir. Permukiman lain yang lepas pada tanggal yang sama: Hama, Humus.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Penyerahan Madinah", "76b505f6"], "d": ["Tujuh puluh dua hari setelah gencatan senjata, perlawanan Fahreddin Paşa, 'Macan Gurun', berakhir atas perintah sultan; unit Utsmaniyah terakhir di Hijaz meletakkan senjata.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Pendudukan İzmir", "e32e5e77"], "d": ["Tentara Yunani mendarat di İzmir; perlawanan yang dimulai dengan peluru pertama menyulut sumbu Perjuangan Nasional. Aydın diduduki pada 27 Mei 1919 (entri terpisah).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Pendudukan resmi Istanbul", "a8e98ada"], "d": ["Pasukan Entente menduduki Istanbul secara resmi, Meclis-i Meb'ûsan dibubarkan; para anggota parlemen menuju Ankara.", "09ed005b"]},
"OLAYLAR_EK:1921-10-13:0":{"b": ["Perjanjian Kars", "bb32d4e0"], "d": ["Antara TBMM dan republik-republik Kaukasus, perbatasan timur digambar dalam bentuknya yang sekarang.", "fe736259"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["Pasukan Saudi-Wahhabi merebut emirat Ha'il — pemerintahan di tangan keluarga Ibn Ali dari suku Abde", "2d29ceb9"], "d": ["Ketika pasukan Negara Saudi Pertama merebut emirat Ha'il, pemerintahan kota berada di tangan keluarga Ibn Ali dari suku Abde dari kabilah Shammar. Keluarga ini memerintah Ha'il hingga Abdullah b. Rashid mengambil alih keamiran pada 1835; dinasti Rashidi baru didirikan pada tanggal itu. Di atlas Ha'il hingga kini tampak tak bertuan hingga 1836, padahal sumber memberi emir kota pada 1820 dengan namanya.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["Beralihnya pulau-pulau Kvarner ke Kerajaan Italia Napoleon, dan Boka Kotorska ke pemerintahan Rusia", "c5e411c8"], "d": ["Setelah Perjanjian Pressburg, pulau-pulau Kvarner — berbeda dengan Dalmatia — diikat bukan langsung ke Prancis melainkan ke Kerajaan Italia Napoleon; mereka baru masuk ke Provinsi Illyria pada 1809. Di Boka Kotorska pemerintahan Austria berakhir dan pemerintahan Rusia didirikan antara 1806-1807; Boka baru beralih ke Prancis pada 1807. Kedua perbedaan ini tidak dapat dipenuhi dengan satu jendela 'Prancis' atlas.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["Beralihnya Dalmatia ke pemerintahan Prancis — penerapan Perjanjian Pressburg", "00bfe4f6"], "d": ["Perjanjian Pressburg 26 Desember 1805 memaksa Austria melepaskan Istria, Dalmatia, dan semua pulau Adriatik. Prancis mengambil alih pemerintahan secara faktual pada Februari 1806; Zadar tetap menjadi pusat proveditor umum dan jabatan ini dijalankan oleh Vicenzo Dandolo dari Venesia antara 1806-1810. Dalmatia bergabung ke Provinsi Illyria setelah Perjanjian Schönbrunn 1809. Pemerintahan Austria pertama yang berlangsung sejak 1797 dengan demikian berakhir — di atlas masa ini hingga kini tampak sebagai Austria tanpa putus.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["Austria merebut kembali Provinsi Illyria dan Dalmatia — berakhirnya pemerintahan Napoleon", "1b2ac942"], "d": ["Pada akhir 1813 pasukan Habsburg merebut kembali wilayah di selatan Sava dan organisasi perbatasan lama didirikan kembali; pasukan Austria memasuki Istria pada Oktober 1813. Karlovac sejak tanggal itu menjadi bagian Kerajaan Illyria Austria. Masa pemerintahan Prancis di Dalmatia juga tertutup pada 1813. Keterikatan wilayah itu pada Austria disahkan secara resmi dengan Perdamaian Paris 1814 dan keputusan Kongres Wina 1815. Dengan operasi ini Villach, Tarvisio, Gorizia, Gradisca, dan Pula (Provinsi Illyria) kembali ke Austria pada akhir 1813.", "bf1e49a8"]},
"OLAYLAR_SENKRON_0930:1298-01-01:0":{"b": ["Maraş beralih ke Mamluk — naib Aleppo Bilbân et-Tabahî merebutnya kembali dari bangsa Armenia", "03171265"], "d": ["Maraş, yang sejak 1258 berada di tangan Kerajaan Armenia Kilikia, dengan perjanjian Sultan Halil dengan bangsa Armenia pada 1293 untuk waktu singkat beralih ke Mamluk dan setelah mereka mundur kembali jatuh ke tangan Armenia. Pada 697 (1298) naib Mamluk di Aleppo Bilbân et-Tabahî merebut kembali kota itu. Maraş setelah itu tetap menjadi tanah Mamluk hingga bangkitnya Dulkadırlı.", "8fd31b13"]},
"OLAYLAR_SENKRON_0930:1372-01-01:0":{"b": ["Kekaisaran Bizantium menjadi pembayar upeti Utsmani", "615df998"], "d": ["Setelah kemenangan Çirmen (1371), kaisar Bizantium Ioannes V pada musim dingin 1372 menerima menjadi pembayar upeti Murad I: ia akan membayar upeti tahunan dan menyediakan pasukan bagi ekspedisi sultan. Bizantium sejak tanggal ini hingga 1403 tetap menjadi negara vasal yang terikat pada Utsmani; blokade Yıldırım Bayezid pada 1391 menaikkan upeti. Setelah kekalahan Ankara, perjanjian Gelibolu (1403) dengan Süleyman Çelebi membebaskan Bizantium dari upeti; dengan perjanjian dengan Murad II pada 1424 upeti dimulai kembali.", "e3c816ac"]},
"OLAYLAR_SENKRON_0930:1399-09-01:0":{"b": ["Yıldırım Bayezid, setelah wafatnya Barquq, memasukkan Besni, Darende, dan Divriği ke tanah Utsmani", "8e57d7e6"], "d": ["Setelah wafatnya Sultan Mamluk Barquq (Juni 1399), ketika urusan administrasi Negara Mamluk kacau, Yıldırım Bayezid turun ke cekungan Efrat dan memasukkan Besni (Behisni), Darende, dan Divriği bersama Malatya ke tanah Utsmani. Sivas sebelum itu diserahkan kepada Utsmani setelah wafatnya Kadı Burhâneddin pada musim panas 1398. Divriği sejak 1391 berada di bawah kekuasaan Mamluk dan merupakan pos terdepan yang terikat pada eyalet Aleppo. Pemerintahan Utsmani di sini tidak berlangsung lama: karena bahaya Timur yang mendekat, Divriği pada 1401 kembali diberikan kepada Mamluk, dan masuknya kota secara pasti ke pemerintahan Utsmani terjadi setelah Marj Dabiq 1516.", "ec7cd171"]},
"OLAYLAR_SENKRON_0930:1400-08-01:0":{"b": ["Besni beralih ke Mamluk pada ekspedisi Timur ke Sivas dan Malatya", "4853da9a"], "d": ["Besni, yang direbut Yıldırım Bayezid pada 1398 bersama Sivas, Darende, dan Malatya, pada 1400 ketika Timur merebut Sivas dan Malatya jatuh ke tangan Mamluk. Timur pada 27 September 1400 setelah pengepungan sengit juga merebut Besni; ketika ia menarik diri dari kawasan itu, Besni kembali masuk ke kekuasaan Mamluk dan tetap di Mamluk (kecuali masa peralihan Dulkadırlı) hingga Yavuz Sultan Selim merebutnya pada Agustus 1516.", "0ead96f9"]},
"OLAYLAR_SENKRON_0930:1401-01-01:0":{"b": ["Divriği diberikan kembali kepada Mamluk karena bahaya Timur", "97196b1f"], "d": ["Divriği, yang diambil Yıldırım Bayezid dari Mamluk pada 1398, ketika Timur mendekati Anatolia pada 1401 ditinggalkan kembali kepada Mamluk. Karena itu setelah Timur menghancurkan Sivas (1400), Divriği tampak di peta berwarna Mamluk; pada bulan-bulan yang sama Bayezid di timur merebut Erzincan dan Kemah, sehingga tanah Mamluk berada di antara tanah Utsmani di barat (Sivas) dan timur laut (Kemah). Divriği baru beralih secara pasti ke Utsmani setelah Marj Dabiq 1516.", "3f13d015"]},
"OLAYLAR_SENKRON_0930:1414-01-01:0":{"b": ["Sultan Mamluk Şeyh merebut kembali Antep dan Darende dari Dulkadırlı", "f90c9508"], "d": ["Sultan Mamluk Şeyh, yang khawatir akan persahabatan Dulkadırlı dengan Utsmani, pada 1414 berekspedisi; ia merebut kembali Antep dan Darende yang sebelumnya atas kehendaknya sendiri ia berikan kepada Dulkadırlı.", "9f9b94e1"]},
"OLAYLAR_SENKRON_0930:1418-01-01:0":{"b": ["Dulkadıroğlu Mehmed Bey merebut kembali Darende dan memasukkan Besni ke wilayahnya", "df914dcb"], "d": ["Darende, yang direbut Mamluk pada 1414, direbut kembali oleh Dulkadıroğlu Mehmed Bey pada 1418 dan ia juga memasukkan Besni ke wilayahnya.", "d469f850"]},
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["Mamluk mengalahkan Dulkadırlı di Antep; Besni kembali ke pemerintahan Mamluk (perkiraan)", "72742430"], "d": ["Tentara Mamluk pada 1436 mengalahkan Dulkadırlı di Antep, Mehmed Bey mundur ke Akdağ. Tahun kembalinya Besni ke Mamluk tidak tertulis dalam sumber; Besni bergabung dengan Dulkadır pada 1418 dan telah kembali ke Mamluk sebelum Şehsuvar Bey mengambilnya dari Mamluk pada 1465. Atlas mengembalikan Besni ke Mamluk bersama kekalahan ini di pusat tetangga Antep (perkiraan yang dinyatakan).", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["Dulkadıroğlu Şehsuvar Bey merebut Besni dari Mamluk (perkiraan)", "843f0fc4"], "d": ["Şehsuvar Bey (1465-1472), yang diangkat Fatih Sultan Mehmed sebagai bey Dulkadır, merebut Besni, Gerger, Birecik, dan Rumkale yang berada di tangan Mamluk; Mamluk dikalahkan di Turnadağı pada musim gugur 1467 dan di dekat Antep pada musim semi 1468.", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["Emîr Yeşbek mengalahkan Şehsuvar Bey; Besni kembali ke pemerintahan Mamluk (perkiraan)", "4d856aee"], "d": ["Pada musim semi 1471 Emîr Yeşbek mengalahkan Şehsuvar Bey di sungai Savron; Mamluk merebut kembali Kadirli dan Kozan. Şehsuvar dihukum mati di Kairo pada 1472, Mamluk mengangkat kembali Şahbudak sebagai bey. Besni pun dengan kembalinya ini masuk ke pemerintahan Mamluk (TDV besni: 'menjelang akhir abad ke-15 kembali jatuh ke tangan Mamluk').", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["Pasukan Ferdinand menduduki dan membentengi Solnok", "6c8416e6"], "d": ["Ketika Utsmani bersiap mendirikan benteng di Solnok di tepi Tisza, pasukan Ferdinand I mendahului: mereka menduduki Solnok pada pertengahan September 1550 dan benteng dibuat dapat dipertahankan pada pertengahan Oktober. Dengan demikian Solnok, yang termasuk negeri Izabella, jatuh ke tangan Habsburg setahun sebelum beralihnya Transilvania ke Ferdinand; Utsmani merebut benteng itu pada 1552.", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["Transilvania beralih ke pemerintahan Habsburg: dewan Kolozsvár mengakui pelepasan hak Izabella", "8458a566"], "d": ["Dengan kesepakatan Martinuzzi dengan Ferdinand, Ratu Izabella atas nama raja kecil János Zsigmond menandatangani surat pelepasan yang dipaksakan kepadanya di benteng Szászsebes pada 19 Juni 1551. Dewan Transilvania yang bersidang di Kolozsvár pada 26 Juli mengakui pelepasan ini dan kedaulatan Raja Ferdinand; tentara Habsburg Jenderal Castaldo memasuki Belgrad Transilvania (Gyulafehérvár). Dengan demikian Transilvania yang terikat pada Utsmani beralih ke pemerintahan Habsburg yang akan berlangsung lima tahun.", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["Pemerintahan Habsburg di Transilvania berakhir: Transilvania kembali menjadi voyvodalık yang terikat Utsmani", "721a482a"], "d": ["Karena János Zsigmond masih kecil, Habsburg dengan perantaraan pastor keturunan Kroasia Martinuzzi (Fráter György) yang diangkat sebagai walinya, pada 1551 mencoba menguasai Transilvania; Belgrad Transilvania (Gyulafehérvár), Kolozsvár, Brassó, dan Segesvár selama lima tahun berada di bawah pemerintahan Habsburg. Utsmani mencegah keadaan ini dan Transilvania kembali menjadi voyvodalık pembayar upeti yang terikat kepadanya. Setelah itu, selama sekitar 150 tahun pada abad ke-16 dan ke-17, Transilvania mempertahankan statusnya yang bertumpu pada otonomi luas dalam urusan dalam negeri dan kesetiaan kepada Istanbul dalam urusan luar negeri.", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["Várad, Huszt, dan Tokaj beralih ke pihak Szapolyai", "587c782d"], "d": ["Setelah kembalinya Izabella dan János Zsigmond ke Transilvania pada 1556, para pendukung Szapolyai pada 1556 mengepung Nagyvárad. Pada 1557 para aristokrat Tisza Hulu merebut benteng-benteng kerajaan terpenting — Várad, Huszt, dan Tokaj; di tangan Ferdinand hanya tersisa Gyula dan Világos. Várad setelah itu menjadi benteng kepangeranan Transilvania dan tetap demikian hingga Utsmani merebutnya pada 1660.", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["Schwendi merebut Szatmár — ujung utara Transilvania beralih ke Habsburg", "2256bb27"], "d": ["Szatmár, yang beralih ke Habsburg pada 1561 dengan berpindahnya pihak Balassa Menyhért, direbut kembali Báthory István dalam serangan mendadak pada musim gugur 1564 dan dimasukkan ke Transilvania. Komandan Habsburg Lazarus von Schwendi melancarkan serangan balasan pada Februari 1565: Tokaj jatuh pada 9 Februari, Szerencs empat hari kemudian, dan Szatmár hampir tanpa perlawanan jatuh ke tangan pasukan kekaisaran.", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["Pasukan Bocskai merebut Szatmár", "e93b098b"], "d": ["Ketika pemberontakan Bocskai menyebar ke Hongaria timur laut, Gyulaffy merebut Szatmár yang dikepungnya pada 21 Januari 1605. Perdamaian Wina 23 Juni 1606 menyerahkan provinsi Szatmár kepada Bocskai seumur hidup; karena tidak ada pewaris laki-laki, dengan wafatnya Bocskai pada 29 Desember 1606 provinsi itu kembali ke kerajaan.", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["Wafatnya Bocskai István — provinsi Szatmár kembali ke kerajaan", "3721bb9b"], "d": ["Pangeran Transilvania Bocskai István wafat di Kassa pada 29 Desember 1606. Perdamaian Wina (23 Juni 1606) telah menyerahkan provinsi-provinsi, termasuk Szatmár, kepadanya seumur hidup, untuk kembali ke kerajaan bila tidak ada pewaris laki-laki; dengan ketentuan ini provinsi Szatmár kembali ke kerajaan Hongaria Habsburg. Transilvania mulai mencari pangeran baru.", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["Bethlen Gábor menguasai provinsi Szatmár", "80263da1"], "d": ["Dengan ekspedisi Bethlen Gábor ke Hongaria pada musim gugur 1619, provinsi Szatmár masuk ke kendali pangeran Transilvania; pada November 1619 ia menyapa provinsi itu melalui surat. Pra-perjanjian 23 Januari 1620 dan Perdamaian Nikolsburg menyerahkan tujuh provinsi, termasuk Szatmár, kepada Bethlen seumur hidup. Setelah wafatnya Bethlen (15 November 1629), pengembalian provinsi-provinsi kepada kerajaan rampung pada 30 Maret 1630.", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["Pengembalian tujuh provinsi Bethlen Gábor kepada kerajaan rampung", "31b5968f"], "d": ["Perdamaian Nikolsburg telah menyerahkan tujuh provinsi Hongaria Hulu, termasuk Szatmár, kepada Bethlen Gábor seumur hidup. Setelah wafatnya Bethlen pada 15 November 1629, pengembalian provinsi-provinsi kepada kerajaan dimulai dengan instruksi 30 November 1629 dan rampung pada 30 Maret 1630.", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["György I Rákóczi menerima penyerahan Szatmár", "f398635b"], "d": ["Pada ekspedisi 1644 pangeran Transilvania György I Rákóczi, garnisun Jerman Szatmár beralih ke dinas Rákóczi dan benteng jatuh ke tangan Transilvania. Perdamaian Linz 16 Desember 1645 menyerahkan benteng itu kepada para pewaris Rákóczi selama seorang Rákóczi duduk di takhta Transilvania.", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["Hilangnya Nitra — De Souches merebut kembali benteng", "c71bf012"], "d": ["Nitra, yang menyerah dengan perlawanan singkat setelah penaklukan Uyvar pada 1663, dikepung komandan kekaisaran De Souches pada 15 April 1664; benteng menyerah pada 3 Mei 1664. Karena Perjanjian Vasvár meninggalkan tempat-tempat yang direbut sebagaimana adanya, Uyvar tetap di Utsmani sedangkan Nitra tetap di tangan Habsburg.", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["Hilangnya Léva", "f311920e"], "d": ["De Souches setelah Nitra mengepung Léva pada 9 Juni 1664; pada 13 Juni ditandatangani kapitulasi dan pada 14 Juni benteng berada di tangan pasukan kekaisaran. Pertempuran Léva (Garamszentbenedek) pada 19 Juli 1664 tidak mengubah kepemilikan; hasilnya Habsburg tetap menguasai Léva dan Nitra.", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["Doroşenko menyerahkan Chigirin kepada Samoylovych", "3b538237"], "d": ["Hetman tepi kanan di bawah perlindungan Utsmani Petro Doroshenko pada 19 September 1676 menyerahkan ibu kotanya Chigirin kepada hetman tepi kiri Samoylovych dan pasukan Rusia. Utsmani mencopot Doroshenko dan mengangkat Yuri Khmelnytsky sebagai gantinya; pengepungan 1677 untuk mengusir garnisun Rusia di Chigirin gagal, benteng baru direbut pada 21 Agustus 1678.", "cccf7b79"]}
});
